P.rep('''# a click on the bars (world thread): null = not a hub click; "self" = redraw this page; "close" = close it; anything else = handled elsewhere
''', '''# 0.3.55 (furnall): the Furnace button: SkyySacks opens its Furnace sub-tab in place of this page ("opened" = handled, no second update), or says no ("info:<text>": the page puts the text on its footer's result line and redraws once)
M(ghub, r"""
public static String furnace(@PR@ pr) {
  java.util.function.Function f = @PKG@.Gear.fn("sacks:fn:openFurnace");
  Object r = null;
  boolean broken = f == null;
  try { if (f != null) r = f.apply(pr.getUuid()); } catch (Throwable t) { r = null; broken = true; @PKG@.Gear.warnOnce("furnaceopen", "sacks:fn:openFurnace failed: " + t); }
  if (Boolean.TRUE.equals(r)) { N[2] = N[2] + 1L; return "opened"; }
  N[3] = N[3] + 1L;
  if (broken) return "info:-The Furnace could not open.";
  return "info:-Equip a Furnace accessory in your Void Charms to use the Furnace.";
}""")
# a click on the bars (world thread): null = not a hub click; "self" = redraw this page; "close" = close it; anything else = handled elsewhere
''')
