P.rep('''    assert sorted(_dead) == sorted(_p for _p, _k in SX_PACK), "The Armory's dead-meter list changed: %s" % sorted(_dead)
''', '''    assert set(_dead) <= set(_p for _p, _k in SX_PACK), "The Armory's dead-meter list changed: %s" % sorted(_dead)
    if sorted(_dead) != sorted(_p for _p, _k in SX_PACK): print("0.3.55 build note: pack items no longer dead-metered: %s" % sorted(set(_p for _p, _k in SX_PACK) - set(_dead)))
''')
# ---- the pages: every one with the Smithing or Upgrade tab lit
